/**
 * Profile sketcher geometry (pure; the React page is ui/ProfileSketcher.tsx).
 *
 * A sketch is a list of loops in profile drawing coordinates (mm, x across =
 * member local y, y up = member local z) plus an insertion point:
 * - 'poly'   closed polygon (outer or hole); a vertex may carry a fillet radius
 *            `r` (corner rounded with a tangent arc) or a bulge `b` (the segment
 *            to the next vertex is an arc);
 * - 'circle' a round outer or hole;
 * - 'wall'   thin-wall centre line (open or closed) with a thickness `t`: the
 *            outline is generated by offsetting ±t/2 with mitred corners, a
 *            vertex `r` is the inner bend radius (outer = r + t). Ideal for
 *            cold-formed and aluminium mullion / transom sections.
 *
 * sketchToShape turns the loops into a POLY shape (one outer, any holes);
 * the catalogue then computes the section properties from it.
 */
import type { Vec2 } from '../model/types';
import { bulgeArc, flattenLoop, loopArea, reverseLoop, segmentPoint, type PolyVertex } from './polyShape';
import { sectionProps, shapeBox, shapeDrawCentre, validateShape, type PolyShape, type SectionProps } from './shapes';
import { STEEL_DENSITY, type ProfileDef } from './profiles';

export interface SketchVertex {
  x: number;
  y: number;
  /** Fillet radius at this vertex (poly corner radius; wall: inner bend radius). */
  r?: number;
  /** Bulge of the segment to the next vertex (poly loops only). */
  b?: number;
}

export type SketchLoop =
  | { id: string; kind: 'poly'; role: 'outer' | 'hole'; pts: SketchVertex[] }
  | { id: string; kind: 'circle'; role: 'outer' | 'hole'; c: Vec2; r: number }
  | { id: string; kind: 'wall'; pts: SketchVertex[]; closed: boolean; t: number };

export interface Sketch {
  version: 1;
  loops: SketchLoop[];
  /** Insertion point (drawing coordinates); null = none (members use the 3×3 grid). */
  insertion: Vec2 | null;
}

export const emptySketch = (): Sketch => ({ version: 1, loops: [], insertion: { x: 0, y: 0 } });

let seq = 0;
export const loopId = (): string => `l${Date.now().toString(36)}${(seq++).toString(36)}`;

const hyp = (a: Vec2, b: Vec2) => Math.hypot(b.x - a.x, b.y - a.y);
const unit = (a: Vec2, b: Vec2): Vec2 => {
  const l = hyp(a, b) || 1;
  return { x: (b.x - a.x) / l, y: (b.y - a.y) / l };
};
const cross = (a: Vec2, b: Vec2) => a.x * b.y - a.y * b.x;
const pv = (x: number, y: number, b?: number): PolyVertex => (b ? { x, y, b } : { x, y });

// ---------------------------------------------------------------------------
// Primitives

/** Axis-aligned rectangle from two opposite corners (counter-clockwise). */
export function rectLoop(a: Vec2, b: Vec2): SketchVertex[] {
  const [x0, x1] = [Math.min(a.x, b.x), Math.max(a.x, b.x)];
  const [y0, y1] = [Math.min(a.y, b.y), Math.max(a.y, b.y)];
  return [
    { x: x0, y: y0 },
    { x: x1, y: y0 },
    { x: x1, y: y1 },
    { x: x0, y: y1 },
  ];
}

/** Circle as two half-circle bulge segments. */
export function circleLoop(c: Vec2, r: number): PolyVertex[] {
  return [pv(c.x + r, c.y, 1), pv(c.x - r, c.y, 1)];
}

/**
 * Round the corners of a polyline with tangent arcs (bulges). `radii[i]` is
 * the radius at vertex i; corners next to an arc segment, end points of open
 * polylines and straight-through vertices stay sharp. A radius too large for
 * the neighbouring edges is reduced so the tangent points stay on them
 * (shared with a filleted neighbour: half the edge each).
 */
export function filletCorners(pts: readonly SketchVertex[], closed: boolean, radii: readonly (number | undefined)[] = pts.map((p) => p.r)): PolyVertex[] {
  const n = pts.length;
  const out: PolyVertex[] = [];
  const has = (i: number) => (radii[(i + n) % n] ?? 0) > 0;
  for (let i = 0; i < n; i++) {
    const P = pts[i];
    const r = radii[i] ?? 0;
    const interior = closed || (i > 0 && i < n - 1);
    const A = pts[(i - 1 + n) % n];
    const B = pts[(i + 1) % n];
    if (!(r > 0) || !interior || A.b || P.b || n < 3) {
      out.push(pv(P.x, P.y, P.b));
      continue;
    }
    const l1 = hyp(P, A);
    const l2 = hyp(P, B);
    const u1 = unit(P, A);
    const u2 = unit(P, B);
    const cos = Math.max(-1, Math.min(1, u1.x * u2.x + u1.y * u2.y));
    const half = Math.acos(cos) / 2;
    if (half < 1e-6 || Math.PI / 2 - half < 1e-6 || l1 < 1e-9 || l2 < 1e-9) {
      out.push(pv(P.x, P.y));
      continue;
    }
    const lim1 = l1 * (has(i - 1) && (closed || i - 1 > 0) ? 0.5 : 1);
    const lim2 = l2 * (has(i + 1) && (closed || i + 1 < n - 1) ? 0.5 : 1);
    const d = Math.min(r / Math.tan(half), lim1, lim2);
    const turn = cross({ x: -u1.x, y: -u1.y }, u2);
    const theta = Math.PI - 2 * half;
    out.push(pv(P.x + u1.x * d, P.y + u1.y * d, Math.tan(theta / 4) * Math.sign(turn)));
    out.push(pv(P.x + u2.x * d, P.y + u2.y * d));
  }
  return out;
}

/** Corner point of two offset lines (mitre), limited for very sharp turns. */
function mitre(p: Vec2, n0: Vec2, n1: Vec2, off: number): Vec2 {
  const m = { x: n0.x + n1.x, y: n0.y + n1.y };
  const ml = Math.hypot(m.x, m.y);
  if (ml < 1e-9) return { x: p.x + n1.x * off, y: p.y + n1.y * off };
  const mu = { x: m.x / ml, y: m.y / ml };
  const c = Math.max(0.05, mu.x * n1.x + mu.y * n1.y);
  return { x: p.x + (mu.x * off) / c, y: p.y + (mu.y * off) / c };
}

/**
 * Outline of a thin wall: the centre line offset by ±t/2 with mitred corners
 * and square ends (open) or an outer and an inner loop (closed). Vertex `r` is
 * the inner bend radius; the outer side of the bend gets r + t. Curved
 * centre-line segments are not supported (their bulges are ignored).
 */
export function thinWallLoops(pts: readonly SketchVertex[], closed: boolean, t: number): { outer: PolyVertex[]; holes: PolyVertex[][] } {
  const P = dedupe(pts, closed);
  const n = P.length;
  if (n < 2 || !(t > 0)) return { outer: [], holes: [] };
  const segs = closed ? n : n - 1;
  const dirs: Vec2[] = [];
  for (let i = 0; i < segs; i++) dirs.push(unit(P[i], P[(i + 1) % n]));
  const nl = dirs.map((d) => ({ x: -d.y, y: d.x }));
  const h = t / 2;
  const left: Vec2[] = [];
  const right: Vec2[] = [];
  const turn: number[] = [];
  for (let i = 0; i < n; i++) {
    const inS = closed ? (i - 1 + segs) % segs : i - 1;
    const outS = closed ? i % segs : i;
    if (inS < 0 || outS >= segs) {
      const s = inS < 0 ? outS : inS;
      left.push({ x: P[i].x + nl[s].x * h, y: P[i].y + nl[s].y * h });
      right.push({ x: P[i].x - nl[s].x * h, y: P[i].y - nl[s].y * h });
      turn.push(0);
      continue;
    }
    left.push(mitre(P[i], nl[inS], nl[outS], h));
    right.push(mitre(P[i], nl[inS], nl[outS], -h));
    turn.push(Math.sign(cross(dirs[inS], dirs[outS])));
  }
  const ri = P.map((p) => Math.max(0, p.r ?? 0));
  // Left turn: the left side is the inside of the bend.
  const rl = ri.map((r, i) => (r > 0 && turn[i] ? (turn[i] > 0 ? r : r + t) : 0));
  const rr = ri.map((r, i) => (r > 0 && turn[i] ? (turn[i] < 0 ? r : r + t) : 0));
  if (!closed) {
    const loop = [...left, ...right.slice().reverse()];
    const radii = [...rl, ...rr.slice().reverse()];
    return { outer: filletCorners(loop, true, radii), holes: [] };
  }
  const L = filletCorners(left, true, rl);
  const R = filletCorners(right, true, rr);
  return Math.abs(loopArea(L)) >= Math.abs(loopArea(R)) ? { outer: L, holes: [R] } : { outer: R, holes: [L] };
}

function dedupe(pts: readonly SketchVertex[], closed: boolean): SketchVertex[] {
  const out: SketchVertex[] = [];
  for (const p of pts) if (!out.length || hyp(out[out.length - 1], p) > 1e-6) out.push(p);
  if (closed && out.length > 1 && hyp(out[0], out[out.length - 1]) < 1e-6) out.pop();
  return out;
}

// ---------------------------------------------------------------------------
// Sketch → shape

/** Loops of one sketch loop in drawing coordinates, with their roles. */
export function loopOutlines(l: SketchLoop): { outer: PolyVertex[][]; holes: PolyVertex[][] } {
  switch (l.kind) {
    case 'circle':
      return l.role === 'outer' ? { outer: [circleLoop(l.c, l.r)], holes: [] } : { outer: [], holes: [circleLoop(l.c, l.r)] };
    case 'poly': {
      const loop = filletCorners(dedupe(l.pts, true), true);
      return l.role === 'outer' ? { outer: [loop], holes: [] } : { outer: [], holes: [loop] };
    }
    case 'wall': {
      const w = thinWallLoops(l.pts, l.closed, l.t);
      return { outer: w.outer.length ? [w.outer] : [], holes: w.holes };
    }
  }
}

export interface SketchResult {
  shape: PolyShape | null;
  errors: string[];
  warnings: string[];
}

/** POLY shape of a sketch: exactly one outer loop, any number of holes, validated. */
export function sketchToShape(s: Sketch): SketchResult {
  const errors: string[] = [];
  const warnings: string[] = [];
  const outers: PolyVertex[][] = [];
  const holes: PolyVertex[][] = [];
  for (const l of s.loops) {
    if (l.kind === 'circle' && !(l.r > 0)) {
      errors.push('A circle has no radius.');
      continue;
    }
    if (l.kind === 'wall') {
      if (!(l.t > 0)) errors.push('A thin wall needs a thickness > 0.');
      if (dedupe(l.pts, l.closed).length < (l.closed ? 3 : 2)) {
        errors.push('A thin wall needs at least 2 points (3 when closed).');
        continue;
      }
      if (l.pts.some((p) => p.b)) warnings.push('Curved thin-wall segments are drawn straight: use bend radii instead.');
    }
    if (l.kind === 'poly' && dedupe(l.pts, true).length < 3 && !l.pts.some((p) => p.b)) {
      errors.push(`A ${l.role === 'hole' ? 'hole' : 'outline'} needs at least 3 points.`);
      continue;
    }
    const o = loopOutlines(l);
    outers.push(...o.outer);
    holes.push(...o.holes);
  }
  if (!outers.length) errors.push('Draw the outline: a closed polyline, a rectangle, a thin wall or a circle.');
  if (outers.length > 1) errors.push(`${outers.length} outer loops: a profile has one outline (draw the others as holes, or join the walls).`);
  if (errors.length) return { shape: null, errors, warnings };
  const orient = (l: PolyVertex[], ccw: boolean) => (loopArea(l) > 0 === ccw ? l : reverseLoop(l));
  const shape: PolyShape = { type: 'POLY', outer: orient(outers[0], true), ...(holes.length ? { holes: holes.map((h) => orient(h, false)) } : {}) };
  const walls = s.loops.filter((l): l is Extract<SketchLoop, { kind: 'wall' }> => l.kind === 'wall');
  if (walls.length && walls.every((w) => w.t === walls[0].t)) shape.t = walls[0].t;
  const err = validateShape(shape);
  if (err) return { shape: null, errors: [err.replace(/^POLY: /, '').replace(/^./, (c) => c.toUpperCase()) + '.'], warnings };
  if (s.insertion) {
    const b = shapeBox(shape);
    const c = shapeDrawCentre(shape);
    if (Math.abs(s.insertion.x - c.x) > b.w || Math.abs(s.insertion.y - c.y) > b.h) warnings.push('The insertion point is far outside the section.');
  } else warnings.push('No insertion point: members place this profile on the 3×3 grid.');
  return { shape, errors, warnings };
}

/** Editable sketch of a POLY shape (outer and holes as polygons with their arcs). */
export function sketchFromShape(shape: PolyShape, insertion: Vec2 | null = null): Sketch {
  const loop = (pts: PolyVertex[], role: 'outer' | 'hole'): SketchLoop => ({ id: loopId(), kind: 'poly', role, pts: pts.map((p) => (p.b ? { x: p.x, y: p.y, b: p.b } : { x: p.x, y: p.y })) });
  return { version: 1, loops: [loop(shape.outer, 'outer'), ...(shape.holes ?? []).map((h) => loop(h, 'hole'))], insertion: insertion ? { ...insertion } : null };
}

/** The sketch stored with a custom profile, or one rebuilt from its outline. Null for parametric profiles. */
export function sketchFromDef(def: Pick<ProfileDef, 'shape' | 'sketch' | 'insertion'>): Sketch | null {
  const sk = def.sketch as Sketch | undefined;
  if (sk && sk.version === 1 && Array.isArray(sk.loops)) return structuredClone({ ...sk, insertion: def.insertion ?? sk.insertion ?? null });
  return def.shape.type === 'POLY' ? sketchFromShape(def.shape, def.insertion ?? null) : null;
}

/** Profile definition from a sketch (throws with the first validation error). */
export function sketchToDef(s: Sketch, meta: { name: string; family?: string; material?: string; mass?: number; spec?: string }): ProfileDef {
  const r = sketchToShape(s);
  if (!r.shape) throw new Error(r.errors[0] ?? 'Invalid sketch');
  const def: ProfileDef = { name: meta.name.trim(), shape: r.shape, sketch: structuredClone(s) };
  if (meta.family?.trim()) def.family = meta.family.trim();
  if (meta.material) def.material = meta.material;
  if (meta.mass !== undefined) def.mass = meta.mass;
  if (meta.spec) def.spec = meta.spec;
  if (s.insertion) def.insertion = { x: s.insertion.x, y: s.insertion.y };
  return def;
}

export interface SketchProps extends SectionProps {
  /** kg/m in the chosen density. */
  mass: number;
  /** Bounding box in drawing coordinates. */
  box: { minX: number; minY: number; maxX: number; maxY: number; w: number; h: number };
  /** Centroid in drawing coordinates. */
  centroid: Vec2;
}

/** Section properties of a shape for the live panel (density kg/m³). */
export function shapeProps(shape: PolyShape, density = STEEL_DENSITY): SketchProps {
  const sp = sectionProps(shape);
  const b = shapeBox(shape);
  const c = shapeDrawCentre(shape);
  return {
    ...sp,
    mass: (sp.area * density) / 1e6,
    box: { minX: c.x - b.w / 2, minY: c.y - b.h / 2, maxX: c.x + b.w / 2, maxY: c.y + b.h / 2, w: b.w, h: b.h },
    centroid: { x: c.x + (sp.cy ?? 0), y: c.y + (sp.cz ?? 0) },
  };
}

// ---------------------------------------------------------------------------
// Insertion point presets

export type InsertionPreset = 'tl' | 'tc' | 'tr' | 'ml' | 'mc' | 'mr' | 'bl' | 'bc' | 'br' | 'centroid';

export const INSERTION_PRESETS: { id: InsertionPreset; label: string }[] = [
  { id: 'tl', label: 'Top left' },
  { id: 'tc', label: 'Top centre' },
  { id: 'tr', label: 'Top right' },
  { id: 'ml', label: 'Middle left' },
  { id: 'mc', label: 'Box centre' },
  { id: 'mr', label: 'Middle right' },
  { id: 'bl', label: 'Bottom left' },
  { id: 'bc', label: 'Bottom centre' },
  { id: 'br', label: 'Bottom right' },
  { id: 'centroid', label: 'Centroid' },
];

/** A preset insertion point of a shape, in drawing coordinates. */
export function insertionPreset(shape: PolyShape, id: InsertionPreset): Vec2 {
  const pr = shapeProps(shape);
  if (id === 'centroid') return pr.centroid;
  const { minX, minY, maxX, maxY } = pr.box;
  const x = id[1] === 'l' ? minX : id[1] === 'r' ? maxX : (minX + maxX) / 2;
  const y = id[0] === 'b' ? minY : id[0] === 't' ? maxY : (minY + maxY) / 2;
  return { x, y };
}

// ---------------------------------------------------------------------------
// Edits (each returns a new sketch)

const mapLoops = (s: Sketch, fn: (l: SketchLoop) => SketchLoop | null): Sketch => ({ ...s, loops: s.loops.map(fn).filter((l): l is SketchLoop => !!l) });

/** Move vertex `i` of a loop (circles: i = 0 moves the centre, i = 1 sets the radius through p). */
export function moveVertex(s: Sketch, id: string, i: number, p: Vec2): Sketch {
  return mapLoops(s, (l) => {
    if (l.id !== id) return l;
    if (l.kind === 'circle') return i === 0 ? { ...l, c: { ...p } } : { ...l, r: Math.max(0.01, hyp(l.c, p)) };
    return { ...l, pts: l.pts.map((v, k) => (k === i ? { ...v, x: p.x, y: p.y } : v)) };
  });
}

/** Delete vertex `i` (a loop left with too few points is removed). */
export function deleteVertex(s: Sketch, id: string, i: number): Sketch {
  return mapLoops(s, (l) => {
    if (l.id !== id) return l;
    if (l.kind === 'circle') return null;
    const pts = l.pts.filter((_, k) => k !== i);
    const min = l.kind === 'wall' ? (l.closed ? 3 : 2) : 3;
    return pts.length < min ? null : { ...l, pts };
  });
}

/** Insert a vertex after index `i` (at p). */
export function insertVertex(s: Sketch, id: string, i: number, p: Vec2): Sketch {
  return mapLoops(s, (l) => (l.id !== id || l.kind === 'circle' ? l : { ...l, pts: [...l.pts.slice(0, i + 1), { x: p.x, y: p.y }, ...l.pts.slice(i + 1)] }));
}

/** Set the fillet / bend radius of a vertex (0 removes it). */
export function setFillet(s: Sketch, id: string, i: number, r: number): Sketch {
  return mapLoops(s, (l) => {
    if (l.id !== id || l.kind === 'circle') return l;
    return { ...l, pts: l.pts.map((v, k) => (k === i ? (r > 0 ? { ...v, r } : { x: v.x, y: v.y, ...(v.b ? { b: v.b } : {}) }) : v)) };
  });
}

/** Set the radius of every vertex of a loop (all corners / bends). */
export function setAllFillets(s: Sketch, id: string, r: number): Sketch {
  const l = s.loops.find((x) => x.id === id);
  if (!l || l.kind === 'circle') return s;
  let out = s;
  l.pts.forEach((_, i) => (out = setFillet(out, id, i, r)));
  return out;
}

export function deleteLoop(s: Sketch, id: string): Sketch {
  return mapLoops(s, (l) => (l.id === id ? null : l));
}

export function updateLoop(s: Sketch, id: string, patch: Partial<SketchLoop>): Sketch {
  return mapLoops(s, (l) => (l.id === id ? ({ ...l, ...patch } as SketchLoop) : l));
}

export function translateSketch(s: Sketch, dx: number, dy: number): Sketch {
  const mv = (p: SketchVertex): SketchVertex => ({ ...p, x: p.x + dx, y: p.y + dy });
  return {
    ...mapLoops(s, (l) => (l.kind === 'circle' ? { ...l, c: { x: l.c.x + dx, y: l.c.y + dy } } : { ...l, pts: l.pts.map(mv) })),
    insertion: s.insertion ? { x: s.insertion.x + dx, y: s.insertion.y + dy } : null,
  };
}

export interface MirrorAxis {
  /** 'x' = mirror about the vertical line x = at (left ↔ right), 'y' = about the horizontal line y = at. */
  axis: 'x' | 'y';
  at: number;
}

/**
 * Mirror the sketch about an axis to make a symmetric section from a half:
 * an open thin wall with an end on the axis is extended by its mirror image
 * (closed when both ends are on it); a polygon with an edge on the axis is
 * opened there and completed by its mirror image; other loops get a mirrored
 * copy (none when the loop is already symmetric about the axis).
 */
export function mirrorSketch(s: Sketch, m: MirrorAxis, tol = 1e-3): Sketch {
  const fx = (p: Vec2): Vec2 => (m.axis === 'x' ? { x: 2 * m.at - p.x, y: p.y } : { x: p.x, y: 2 * m.at - p.y });
  const on = (p: Vec2) => Math.abs((m.axis === 'x' ? p.x : p.y) - m.at) < tol;
  const vtx = (p: Vec2, r?: number, b?: number): SketchVertex => {
    const q: SketchVertex = { x: p.x, y: p.y };
    if (r) q.r = r;
    if (b) q.b = b;
    return q;
  };
  const sameSet = (a: Vec2[], b: Vec2[]) => a.length === b.length && a.every((p) => b.some((q) => hyp(p, q) < tol));
  const loops: SketchLoop[] = [];
  for (const l of s.loops) {
    if (l.kind === 'circle') {
      loops.push(l);
      if (!on(l.c)) loops.push({ ...l, id: loopId(), c: fx(l.c) });
      continue;
    }
    const pts = l.pts;
    const n = pts.length;
    if (l.kind === 'wall' && !l.closed && n >= 2 && (on(pts[0]) || on(pts[n - 1]))) {
      // Orient the run so it ends on the axis, then come back out along its mirror image.
      const run = on(pts[n - 1]) ? pts.slice() : pts.slice().reverse();
      const all = [...run, ...run.slice(0, -1).reverse().map((p) => vtx(fx(p), p.r))];
      const closed = on(pts[0]) && on(pts[n - 1]);
      loops.push({ ...l, pts: closed ? all.slice(0, -1) : all, closed });
      continue;
    }
    if (l.kind === 'poly') {
      const k = pts.findIndex((p, i) => on(p) && on(pts[(i + 1) % n]) && !p.b);
      if (k >= 0 && n >= 2) {
        // C = the polygon from the vertex after the axis edge round to the one before it (both on the axis);
        // the result is C followed by its mirror image walked backwards. The segment m(C[j]) → m(C[j−1])
        // is the mirror of C[j−1] → C[j] reversed, so it keeps that segment's bulge.
        const C = Array.from({ length: n }, (_, j) => pts[(k + 1 + j) % n]);
        const out: SketchVertex[] = [];
        for (let j = 0; j <= n - 2; j++) out.push(vtx(C[j], C[j].r, C[j].b));
        out.push(vtx(C[n - 1], C[n - 1].r, C[n - 2].b));
        for (let j = n - 2; j >= 1; j--) out.push(vtx(fx(C[j]), C[j].r, C[j - 1].b));
        loops.push({ ...l, pts: out });
        continue;
      }
    }
    loops.push(l);
    // Mirrored copy (a mirror turns every arc the other way).
    const copy = pts.map((p) => vtx(fx(p), p.r, l.kind === 'poly' && p.b ? -p.b : undefined));
    if (!sameSet(copy, pts)) loops.push({ ...l, id: loopId(), pts: copy } as SketchLoop);
  }
  return { ...s, loops };
}

// ---------------------------------------------------------------------------
// Input: typed coordinates and snapping

/**
 * Typed point: "x,y" (absolute), "@dx,dy" (relative to the last point),
 * "@L<angle" (polar, relative; degrees counter-clockwise from +x) or "L<angle"
 * (polar from the origin). Separators "," ";" or a space. Null when invalid.
 */
export function parseCoord(text: string, last: Vec2 | null): Vec2 | null {
  const t = text.trim().replace(/\s*([<,;@])\s*/g, '$1');
  if (!t) return null;
  const rel = t.startsWith('@');
  const body = rel ? t.slice(1) : t;
  const base = rel ? (last ?? { x: 0, y: 0 }) : { x: 0, y: 0 };
  const num = (s: string) => (s.trim() === '' ? NaN : Number(s));
  const polar = body.split('<');
  if (polar.length === 2) {
    const L = num(polar[0]);
    const a = (num(polar[1]) * Math.PI) / 180;
    if (!Number.isFinite(L) || !Number.isFinite(a)) return null;
    return { x: base.x + L * Math.cos(a), y: base.y + L * Math.sin(a) };
  }
  const parts = body.split(/[,; ]+/).filter(Boolean);
  if (parts.length !== 2) return null;
  const [x, y] = parts.map(num);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  return { x: base.x + x, y: base.y + y };
}

export type SnapKind = 'vertex' | 'midpoint' | 'centre' | 'insertion' | 'origin' | 'axis' | 'grid' | 'ortho' | 'none';

export interface SnapOptions {
  /** Grid step, mm (0 = off). */
  grid: number;
  /** Snap distance, mm (in the current zoom). */
  tol: number;
  vertices?: boolean;
  midpoints?: boolean;
  /** The x = 0 and y = 0 axes. */
  axes?: boolean;
  /** Keep horizontal / vertical from this point when within tol. */
  from?: Vec2 | null;
  /** Extra candidate points (e.g. the points of the loop being drawn). */
  extra?: Vec2[];
}

/** Points a click can snap to: vertices, segment midpoints, circle centres and the insertion point. */
export function snapCandidates(s: Sketch): { p: Vec2; kind: SnapKind }[] {
  const out: { p: Vec2; kind: SnapKind }[] = [];
  for (const l of s.loops) {
    if (l.kind === 'circle') {
      out.push({ p: l.c, kind: 'centre' });
      for (const a of [0, 90, 180, 270]) out.push({ p: { x: l.c.x + l.r * Math.cos((a * Math.PI) / 180), y: l.c.y + l.r * Math.sin((a * Math.PI) / 180) }, kind: 'vertex' });
      continue;
    }
    const n = l.pts.length;
    const closed = l.kind === 'poly' || l.closed;
    l.pts.forEach((p, i) => {
      out.push({ p, kind: 'vertex' });
      if (i < n - 1 || closed) out.push({ p: segmentPoint(p, l.pts[(i + 1) % n], l.kind === 'poly' ? p.b : 0, 0.5), kind: 'midpoint' });
    });
  }
  if (s.insertion) out.push({ p: s.insertion, kind: 'insertion' });
  return out;
}

/** Snap a cursor point: vertices / midpoints / centres first, then the origin and axes, ortho, then the grid. */
export function snapPoint(p: Vec2, s: Sketch, o: SnapOptions): { p: Vec2; kind: SnapKind } {
  let best: { p: Vec2; kind: SnapKind } | null = null;
  let bestD = o.tol;
  const cands = snapCandidates(s).filter((c) => (c.kind === 'midpoint' ? o.midpoints !== false : o.vertices !== false));
  for (const q of o.extra ?? []) cands.push({ p: q, kind: 'vertex' });
  if (o.axes !== false) cands.push({ p: { x: 0, y: 0 }, kind: 'origin' });
  for (const c of cands) {
    const d = hyp(p, c.p);
    if (d < bestD - 1e-9 || (best && Math.abs(d - bestD) < 1e-9 && c.kind === 'vertex' && best.kind !== 'vertex')) {
      best = { p: { ...c.p }, kind: c.kind };
      bestD = d;
    }
  }
  if (best) return best;
  const g = o.grid > 0 ? (v: number) => Math.round(v / o.grid) * o.grid : (v: number) => v;
  let x = g(p.x);
  let y = g(p.y);
  let kind: SnapKind = o.grid > 0 ? 'grid' : 'none';
  if (o.from) {
    if (Math.abs(p.y - o.from.y) < o.tol) {
      y = o.from.y;
      kind = 'ortho';
    } else if (Math.abs(p.x - o.from.x) < o.tol) {
      x = o.from.x;
      kind = 'ortho';
    }
  }
  if (o.axes !== false) {
    if (Math.abs(p.x) < o.tol) {
      x = 0;
      kind = 'axis';
    }
    if (Math.abs(p.y) < o.tol) {
      y = 0;
      kind = 'axis';
    }
  }
  return { p: { x, y }, kind };
}

/** Nearest vertex of the sketch (loop id, index) within tol, for editing. Circles: 0 = centre, 1 = on the rim. */
export function pickVertex(s: Sketch, p: Vec2, tol: number): { id: string; i: number } | null {
  let best: { id: string; i: number } | null = null;
  let bd = tol;
  for (const l of s.loops) {
    const pts = l.kind === 'circle' ? [l.c, { x: l.c.x + l.r, y: l.c.y }] : l.pts;
    pts.forEach((q, i) => {
      const d = hyp(p, q);
      if (d < bd) {
        bd = d;
        best = { id: l.id, i };
      }
    });
  }
  return best;
}

/** Nearest segment of a loop to p within tol: loop id and the index of its first vertex. */
export function pickSegment(s: Sketch, p: Vec2, tol: number): { id: string; i: number; at: Vec2 } | null {
  let best: { id: string; i: number; at: Vec2 } | null = null;
  let bd = tol;
  for (const l of s.loops) {
    if (l.kind === 'circle') continue;
    const n = l.pts.length;
    const closed = l.kind === 'poly' || l.closed;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      const a = l.pts[i];
      const b = l.pts[(i + 1) % n];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const L2 = dx * dx + dy * dy;
      if (L2 < 1e-12) continue;
      const t = Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / L2));
      const q = { x: a.x + dx * t, y: a.y + dy * t };
      const d = hyp(p, q);
      if (d < bd) {
        bd = d;
        best = { id: l.id, i, at: q };
      }
    }
  }
  return best;
}

/** Flattened preview polylines of every loop (drawing coordinates), with the generated wall outlines. */
export function sketchPreview(s: Sketch): { id: string; kind: SketchLoop['kind']; role: 'outer' | 'hole' | 'centre'; pts: Vec2[]; closed: boolean }[] {
  const out: { id: string; kind: SketchLoop['kind']; role: 'outer' | 'hole' | 'centre'; pts: Vec2[]; closed: boolean }[] = [];
  for (const l of s.loops) {
    const o = loopOutlines(l);
    for (const loop of o.outer) out.push({ id: l.id, kind: l.kind, role: 'outer', pts: flattenLoop(loop), closed: true });
    for (const loop of o.holes) out.push({ id: l.id, kind: l.kind, role: 'hole', pts: flattenLoop(loop), closed: true });
    if (l.kind === 'wall') out.push({ id: l.id, kind: 'wall', role: 'centre', pts: l.pts.map((p) => ({ x: p.x, y: p.y })), closed: l.closed });
  }
  return out;
}

/** Arc radius of a vertex's bulge segment (for labels), or 0. */
export function bulgeRadius(a: Vec2, b: Vec2, bulge?: number): number {
  return bulgeArc(a, b, bulge)?.r ?? 0;
}
